#' 
#' 
#' 
#' 
addNewDrawnMutation <- function(mutationType, position, originSubpop = NULL, nucleotide = NULL) {
  Ha$addNewDrawnMutation(mutationType, position, originSubpop = NULL, nucleotide = NULL)
}

