#' @author Benjamin C Haller (\email{bhaller@@benhaller.com}) and Philipp W Messer (\email{messer@@cornell.edu})
#' 
#' 
#' 
#' 
treeSeqOutput <- function(path, simplify = NULL, includeModel = NULL, metadata = NULL, overwriteDirectory = NULL) {
  Sp$treeSeqOutput(path, simplify = NULL, includeModel = NULL, metadata = NULL, overwriteDirectory = NULL)
}

