#' @export
#' @examples
#' ## This just brings up the documentation:
#' calcLD_D()
calcLD_D <- function(mut1, mut2 = NULL, haplosomes = NULL) {
  SB$calcLD_D(mut1, mut2 = NULL, haplosomes = NULL)
}

