#' @author Benjamin C Haller (\email{bhaller@@benhaller.com}) and Philipp W Messer (\email{messer@@cornell.edu})
#' @export
eidos_grep <- function(pattern, x, ignoreCase = NULL, grammar = NULL, value = NULL, fixed = NULL, invert = NULL) {
  E$grep(pattern, x, ignoreCase = NULL, grammar = NULL, value = NULL, fixed = NULL, invert = NULL)
}

